/* ── Header row ───────────────────────────────────────────── */
.learn-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.2rem;
  flex-wrap: wrap;
  gap: .8rem;
}
.learn-header-left h1 {
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0 0 .15rem;
}
.learn-header-left p {
  font-size: .8rem;
  color: var(--text-muted);
  margin: 0;
}
.learn-time-row {
  display: flex;
  align-items: center;
  gap: .6rem;
}
.learn-time-val {
  font-size: .8rem;
  color: var(--text-muted);
}

/* ── Session progress bar (remaining cards) ───────────────── */
.session-progress-wrap {
  margin-bottom: 1.4rem;
}
.session-progress-label {
  display: flex;
  justify-content: space-between;
  font-size: .72rem;
  color: var(--text-dim);
  margin-bottom: .35rem;
}

/* ── Phase badge ──────────────────────────────────────────── */
.phase-badge {
  display: inline-block;
  background: rgba(0,170,255,.15);
  border: 1px solid rgba(0,170,255,.3);
  border-radius: 100px;
  font-size: .72rem;
  padding: .3rem .9rem;
  color: var(--accent-1);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: .9rem;
}
.group-badge {
  display: inline-block;
  background: rgba(94,231,223,.12);
  border: 1px solid rgba(94,231,223,.25);
  border-radius: 100px;
  font-size: .68rem;
  padding: .25rem .75rem;
  color: var(--accent-3);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .05em;
  margin-left: .5rem;
}

/* ── Flashcard container ──────────────────────────────────── */
.learn-card {
  background: linear-gradient(135deg, rgba(0,170,255,.15), rgba(255,79,94,.10));
  border: 1px solid rgba(0,170,255,.35);
  border-radius: var(--radius-xl);
  box-shadow: 0 0 40px rgba(0,170,255,.18), 0 8px 32px rgba(0,0,0,.3);
  padding: 2.2rem 2rem 1.8rem;
  text-align: center;
  position: relative;
  overflow: hidden;
  transition: box-shadow .3s;
}
.learn-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 60% 20%, rgba(0,170,255,.08), transparent 65%);
  pointer-events: none;
}

/* ── Main character display ───────────────────────────────── */
.card-char-study {
  font-family: 'Noto Sans KR', 'Inter', sans-serif;
  font-size: 6.5rem;
  font-weight: 700;
  line-height: 1.1;
  background: linear-gradient(135deg, var(--accent-1), var(--accent-2));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: .4rem;
  user-select: none;
}
.card-char-quiz {
  font-family: 'Noto Sans KR', 'Inter', sans-serif;
  font-size: 4rem;
  font-weight: 700;
  line-height: 1.1;
  background: linear-gradient(135deg, var(--accent-1), var(--accent-2));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: .6rem;
  user-select: none;
}

/* ── Study phase: reading & romanji ──────────────────────── */
.study-reading {
  font-size: 2rem;
  font-weight: 700;
  color: var(--accent-3);
  font-family: 'Noto Sans KR', 'Inter', sans-serif;
  margin-bottom: .25rem;
  letter-spacing: .04em;
}
.study-romanji {
  font-size: 1rem;
  color: var(--text-muted);
  letter-spacing: .06em;
  margin-bottom: 1.2rem;
}

/* ── Mnemonic / notes box ─────────────────────────────────── */
.mnemonic-box {
  background: rgba(255,190,85,.1);
  border: 1px solid rgba(255,190,85,.25);
  border-radius: 10px;
  padding: .8rem 1rem;
  text-align: left;
  font-size: .88rem;
  color: var(--text-primary);
  display: flex;
  gap: .6rem;
  align-items: flex-start;
  margin-top: .6rem;
}
.mnemonic-icon { font-size: 1.1rem; flex-shrink: 0; margin-top: .05rem; }
.mnemonic-text { line-height: 1.55; }

/* ── Countdown bar ────────────────────────────────────────── */
.countdown-wrap { margin-top: 1.4rem; position: relative; }
.countdown-track { height: 4px; background: rgba(255,255,255,.08); border-radius: 100px; overflow: hidden; }
.countdown-fill {
  height: 100%; width: 100%;
  background: linear-gradient(90deg, var(--accent-1), var(--accent-2));
  border-radius: 100px;
  animation: countdown 4s linear forwards;
}
@keyframes countdown { from { width: 100%; } to { width: 0%; } }
.countdown-label { font-size: .68rem; color: var(--text-dim); text-align: center; margin-top: .4rem; }

/* ── "Skip to quiz" button ────────────────────────────────── */
.skip-btn {
  margin-top: 1rem; width: 100%; padding: .75rem 1rem;
  border-radius: var(--radius-md); background: rgba(255,255,255,.06);
  border: 1px solid var(--border); color: var(--text-muted);
  font-size: .88rem; cursor: pointer;
  transition: background .2s, color .2s, border-color .2s;
  font-family: 'Inter', sans-serif;
}
.skip-btn:hover { background: rgba(0,170,255,.12); border-color: rgba(0,170,255,.4); color: var(--accent-1); }
.skip-btn kbd {
  display: inline-block; background: rgba(255,255,255,.1);
  border: 1px solid rgba(255,255,255,.15); border-radius: 4px;
  padding: .05rem .35rem; font-size: .75rem; margin: 0 .15rem;
}

/* ── Quiz phase ───────────────────────────────────────────── */
#quiz-phase { display: none; }

/* ── Quiz input ───────────────────────────────────────────── */
.quiz-input-wrap {
  display: flex; align-items: center; gap: .6rem;
  max-width: 460px; margin: 1.2rem auto 0;
}
#quiz-input {
  width: 100%; padding: .85rem 1.2rem;
  border-radius: var(--radius-md);
  background: rgba(255,255,255,.06);
  border: 2px solid var(--border);
  color: var(--text-primary); font-size: 1.35rem;
  font-family: 'Noto Sans KR', 'Inter', sans-serif;
  text-align: center; outline: none;
  transition: border-color .2s, box-shadow .2s; letter-spacing: .08em;
}
#quiz-input:focus { border-color: var(--accent-1); box-shadow: 0 0 0 3px rgba(0,170,255,.18); }
#quiz-input.correct { border-color: var(--accent-ok); box-shadow: 0 0 0 3px rgba(94,231,160,.2); background: rgba(94,231,160,.07); }
#quiz-input.wrong { border-color: var(--accent-bad); box-shadow: 0 0 0 3px rgba(255,107,107,.2); background: rgba(255,107,107,.07); animation: shake .35s ease; }
@keyframes shake {
  0%,100% { transform: translateX(0); }
  20%      { transform: translateX(-8px); }
  60%      { transform: translateX(8px); }
  80%      { transform: translateX(-4px); }
}
.quiz-submit-btn {
  padding: .85rem 1.4rem; border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--accent-1), var(--accent-2));
  color: #fff; border: none; font-weight: 700; font-size: 1rem;
  cursor: pointer; white-space: nowrap;
  transition: transform .15s, box-shadow .15s; flex-shrink: 0;
  font-family: 'Inter', sans-serif;
}
.quiz-submit-btn:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(0,170,255,.4); }

/* ── Feedback panel ───────────────────────────────────────── */
#feedback-panel {
  display: none; max-width: 460px; margin: 1rem auto 0;
  padding: 1rem 1.2rem; border-radius: var(--radius-md);
  text-align: center; animation: fadeIn .25s ease;
}
@keyframes fadeIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
#feedback-panel.ok  { background: rgba(94,231,160,.1); border: 1px solid rgba(94,231,160,.3); color: var(--accent-ok); }
#feedback-panel.bad { background: rgba(255,107,107,.1); border: 1px solid rgba(255,107,107,.3); color: var(--accent-bad); }
.feedback-main { font-size: 1.15rem; font-weight: 700; margin-bottom: .3rem; }
.feedback-sub  { font-size: .85rem; opacity: .85; }

/* ── "Continue anyway" button (shown on wrong answer) ─────── */
#continue-btn {
  display: none; max-width: 460px; margin: .8rem auto 0; width: 100%;
  padding: .75rem 1.2rem; border-radius: var(--radius-md);
  background: rgba(255,255,255,.06); border: 1px solid var(--border);
  color: var(--text-muted); font-size: .9rem; cursor: pointer;
  transition: background .2s, color .2s; font-family: 'Inter', sans-serif;
}
#continue-btn:hover { background: rgba(255,107,107,.12); color: var(--accent-bad); }

/* ── Hidden learn form ────────────────────────────────────── */
#learn-form { display: none; }

/* ── Pause overlay ────────────────────────────────────────── */
#pause-overlay {
  display: none; position: fixed; inset: 0;
  background: rgba(13,13,20,.88); backdrop-filter: blur(10px);
  z-index: 200; align-items: center; justify-content: center;
  flex-direction: column; gap: 1rem;
}
#pause-overlay.visible { display: flex; }
.pause-icon { font-size: 3.5rem; }
.pause-text { font-size: 1.1rem; color: var(--text-muted); }

